472	  <script>
473	    // === Menu ===
474	    function toggleMenu() {
475	      var dropdown = document.getElementById('vizMenuDropdown');
476	      if (dropdown) dropdown.classList.toggle('open');
477	    }
478	    document.addEventListener('click', function(e) {
479	      if (!e.target.closest('.viz-menu')) {
480	        var dropdown = document.getElementById('vizMenuDropdown');
481	        if (dropdown) dropdown.classList.remove('open');
482	      }
483	    });
484	    document.addEventListener('keydown', function(e) {
485	      if (e.key === 'Escape') {
486	        var dropdown = document.getElementById('vizMenuDropdown');
487	        if (dropdown) dropdown.classList.remove('open');
488	      }
489	    });
