491	    // === Theme ===
492	    var savedTheme = localStorage.getItem('viz-theme');
493	    var currentTheme = savedTheme || 'dark';
494	    function applyTheme(t) {
495	      document.documentElement.className = 'theme-' + t;
496	      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
497	      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
498	      localStorage.setItem('viz-theme', t);
499	      currentTheme = t;
500	      if (typeof onThemeChange === 'function') onThemeChange();
501	    }
502	    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
503	    applyTheme(currentTheme);
504	
505	    // === Scroll Reveal ===
506	    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
507	    var revealObserver = new IntersectionObserver(function(entries) {
508	      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
509	    }, { threshold: 0.15 });
510	    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
511	
512	    // === Number Counter ===
513	    function animateCounters() {
514	      document.querySelectorAll('[data-count]').forEach(function(el) {
515	        if (el.dataset.counted) return;
516	        el.dataset.counted = '1';
517	        var target = parseFloat(el.dataset.count);
518	        var suffix = el.dataset.suffix || '';
519	        var isDecimal = String(target).indexOf('.') !== -1;
520	        var start = performance.now();
521	        var duration = 1400;
522	        (function tick(now) {
523	          var p = Math.min((now - start) / duration, 1);
524	          var eased = 1 - Math.pow(1 - p, 3);
525	          var val = target * eased;
526	          if (isDecimal) {
527	            el.textContent = val.toFixed(1) + suffix;
528	          } else {
529	            el.textContent = Math.round(val) + suffix;
530	          }
531	          if (p < 1) requestAnimationFrame(tick);
532	        })(start);
533	      });
534	    }
535	    var counterEl = document.querySelector('[data-count]');
536	    if (counterEl) {
537	      var cObs = new IntersectionObserver(function(entries) {
538	        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
539	      }, { threshold: 0.3 });
540	      cObs.observe(counterEl);
541	    }
542	
543	    // === Download PNG ===
544	    async function downloadImage() {
545	      var menu = document.querySelector('.viz-menu');
546	      menu.style.display = 'none';
547	      try {
548	        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
549	        var a = document.createElement('a'); a.href = url;
550	        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
551	      } catch(e) { console.error('Download failed:', e); }
552	      menu.style.display = '';
553	    }
554	
555	    function onThemeChange() {}
556	  </script>
