[metadata] {"type": "text", "file": {"filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>\n<html lang=\"en\" class=\"theme-dark\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Hunger Doesn't Wait — Together We Can End It</title>\n  <link href=\"/app/libs/fonts/inter.css\" rel=\"stylesheet\">\n  <script src=\"/app/libs/html-to-image.js\"></script>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root { interpolate-size: allow-keywords; }\n\n    /* ===== THEMES — warm advocacy palette ===== */\n    html.theme-dark {\n      --bg: #0C0804; --surface: #1A1408; --surface-hover: #241C0E;\n      --border: rgba(232, 116, 12, 0.10);\n      --text: #F5EDE4; --text-secondary: #A89080;\n      --accent: #E8740C; --accent-secondary: #C2410C;\n      --positive: #D4A017; --negative: #E84040; --warning: #F59E0B;\n      --warm-glow: rgba(232, 116, 12, 0.06);\n      --stat-bg: rgba(232, 116, 12, 0.07);\n    }\n    html.theme-light {\n      --bg: #FBF7F0; --surface: #FFFFFF; --surface-hover: #F5EFE5;\n      --border: rgba(180, 100, 20, 0.10);\n      --text: #1C1008; --text-secondary: #6B5740;\n      --accent: #D46408; --accent-secondary: #B83A08;\n      --positive: #B89010; --negative: #CC3030; --warning: #D48A06;\n      --warm-glow: rgba(212, 100, 8, 0.04);\n      --stat-bg: rgba(212, 100, 8, 0.05);\n    }\n\n    body {\n      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n      background: var(--bg); color: var(--text);\n      line-height: 1.6; -webkit-font-smoothing: antialiased;\n      letter-spacing: -0.01em; font-feature-settings: 'cv11', 'ss01';\n      transition: background 0.3s, color 0.3s;\n      width: 1080px; height: 1520px;\n      overflow: hidden;\n      display: flex; flex-direction: column;\n      position: relative;\n    }\n\n    /* Background atmosphere — warm radial glow */\n    body::bef