    }\n    .impact-hero {\n      display: flex; align-items: baseline; gap: 24px;\n      margin-bottom: 20px;\n    }\n    .impact-hero .big-number {\n      font-size: 104px; font-weight: 800; letter-spacing: -0.05em;\n      line-height: 0.9; color: var(--positive);\n    }\n    .impact-hero .big-label {\n      font-size: 26px; font-weight: 600; color: var(--text);\n      max-width: 300px; line-height: 1.2;\n    }\n    .impact-grid {\n      display: grid; grid-template-columns: repeat(3, 1fr);\n      gap: 16px;\n    }\n    .impact-card {\n      background: var(--stat-bg); border: 1px solid var(--border);\n      border-radius: 10px; padding: 20px 22px;\n    }\n    .impact-card .metric-value {\n      font-size: 32px; font-weight: 700; color: var(--text);\n      letter-spacing: -0.03em; line-height: 1.1;\n    }\n    .impact-card .metric-label {\n      font-size: 14px; color: var(--text-secondary); margin-top: 4px;\n      line-height: 1.4;\n    }\n\n    /* How we unite */\n    .pillars-section {\n      padding: 36px 60px 0;\n      position: relative; z-index: 1;\n    }\n    .pillars-section .section-label {\n      font-size: 14px; font-weight: 600; letter-spacing: 0.12em;\n      text-transform: uppercase; color: var(--accent);\n      margin-bottom: 16px;\n    }\n    .pillars-grid {\n      display: grid; grid-template-columns: repeat(4, 1fr);\n      gap: 14px;\n    }\n    .pillar-card {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 18px 16px;\n    }\n    .pillar-card .pillar-icon {\n      width: 32px; height: 32px; margin-bottom: 10px;\n      color: var(--accent);\n    }\n    .pillar-card .pillar-title {\n      font-size: 14px; font-weight: 600; color: var(--text);\n      margin-bottom: 6px;\n    }\n    .pillar-card .pillar-desc {\n      font-size: 12px; color: var(--text-secondary); line-height: 1.5;\n    }\n\n    /* CTA section */\n    .action-section {\n      padding: 36px 60px 44px;\n      position: relative; z-index: 1;\n      flex: 1; display: flex; flex-direction: column; justify-content: flex-end;\n    }\n    .conversion-strip {\n      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);\n      border-radius: 14px; padding: 24px 32px;\n      display: flex; align-items: center; justify-content: space-between;\n      margin-bottom: 20px;\n    }\n    .conversion-strip .conv-left {\n      display: flex; align-items: baseline; gap: 12px;\n    }\n    .conversion-strip .conv-number {\n      font-size: 52px; font-weight: 800; color: #fff;\n      letter-spacing: -0.04em; line-height: 1;\n    }\n    .conversion-strip .conv-text {\n      font-size: 20px; font-weight: 600; color: rgba(255,255,255,0.9);\n      line-height: 1.3;\n    }\n    .conversion-strip .conv-badge {\n      background: rgba(255,255,255,0.2);\n      border-radius: 8px; padding: 8px 16px;\n      font-size: 13px; font-weight: 600; color: #fff;\n      letter-spacing: 0.04em; text-transform: uppercase;\n    }\n\n    .cta-grid {\n      display: grid; grid-template-columns: repeat(4, 1fr);\n      gap: 14px;\n    }\n    .cta-card {\n      background: var(--surface); border: 1px solid var(--border);\n      border-radius: 10px; padding: 18px 16px;\n      text-align: center;\n      transition: box-shadow 0.2s ease;\n    }\n    .cta-card:hover {\n      box-shadow: 0 0 0 1px var(--accent), 0 8px 24px rgba(232, 116, 12, 0.12);\n    }\n    .cta-card .cta-icon {\n      width: 36px; height: 36px; margin: 0 auto 10px;\n      color: var(--accent);\n    }\n    .cta-card .cta-title {\n      font-size: 16px; font-weight: 700; color: var(--accent);\n      margin-bottom: 6px; letter-spacing: -0.02em;\n    }\n    .cta-card .cta-desc {\n      font-size: 12px; color: var(--text-secondary); line-height: 1.5;\n    }\n\n    /* Divider line */\n    .divider {\n      width: 100%; height: 1px;\n      background: linear-gradient(90deg, transparent, var(--border), var(--accent), var(--border), transparent);\n      margin: 0;\n    }\n\n    /* ===== RESPONSIVE (for viewing at smaller sizes) ===== */\n    @media (max-width: 375px) {\n      body { overflow-x: hidden; }\n    }\n  </style>\n</head>\n<body>\n  <a href=\"#main-content\" class=\"skip-to-content\">Skip to content</a>\n\n  <main id=\"main-content\" role=\"main\">\n\n  <!-- MENU -->\n  <div class=\"viz-menu\">\n    <button class=\"viz-menu-toggle\" onclick=\"toggleMenu()\" aria-label=\"Menu\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n        <line x1=\"3\" y1=\"5\" x2=\"17\" y2=\"5\"/><line x1=\"3\" y1=\"10\" x2=\"17\" y2=\"10\"/><line x1=\"3\" y1=\"15\" x2=\"17\" y2=\"15\"/>\n      </svg>\n    </button>\n    <div class=\"viz-menu-dropdown\" id=\"vizMenuDropdown\">\n      <button onclick=\"cycleTheme()\"><span id=\"themeIcon\">🌙</span><span id=\"themeLabel\">Dark</span></button>\n      <button onclick=\"downloadImage()\"><span>📥</span><span>Download PNG</span></button>\n      <button onclick=\"window.print()\"><span>🖨️</span><span>Print / PDF</span></button>\n    </div>\n  </div>\n\n  <!-- HEADER — Title -->\n  <section class=\"poster-header animate\" aria-label=\"Poster headline\">\n    <div class=\"overline\">Feeding America</div>\n    <h1>Hunger Doesn't Wait — <span class=\"accent-word\">Together We Can End It</span></h1>\n    <p class=\"subtitle\">48 million Americans face hunger, but a united network of food banks, volunteers, and advocates is fighting back with billions of meals every year.</p>\n  </section>\n\n  <!-- CRISIS — 48 Million -->\n  <section class=\"crisis-section animate delay-1\" aria-label=\"Hunger crisis statistics\">\n    <div class=\"crisis-hero\">\n      <div class=\"big-number\" data-count=\"48\" data-suffix=\"M\">48M</div>\n      <div class=\"big-label\">people face hunger across the United States</div>\n    </div>\n    <p class=\"crisis-sub\">Including <strong>14 million children</strong> — families in every state, urban and rural alike, struggle to put nutritious food on the table.</p>\n  </section>\n\n  <div class=\"divider\"></div>\n\n  <!-- IMPACT — 5.7 Billion Meals -->\n  <section class=\"impact-section animate delay-2\" aria-label=\"Network impact statistics\">\n    <div class=\"section-label\">Our Collective Impact</div>\n    <div class=\"impact-hero\">\n      <div class=\"big-number\" data-count=\"5.7\" data-suffix=\"B\">5.7B</div>\n      <div class=\"big-label\">meals distributed through the network</div>\n    </div>\n    <div class=\"impact-grid\">\n      <div class=\"impact-card\">\n        <div class=\"metric-value\">4.3B lbs</div>\n        <div class=\"metric-label\">Food rescued from waste</div>\n      </div>\n      <div class=\"impact-card\">\n        <div class=\"metric-value\">60,000+</div>\n        <div class=\"metric-label\">Free food programs</div>\n      </div>\n      <div class=\"impact-card\">\n        <div class=\"metric-value\">200+</div>\n        <div class=\"metric-label\">Food banks nationwide</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- PILLARS — How We Unite -->\n  <section class=\"pillars-section animate delay-3\" aria-label=\"How we unite communities\">\n    <div class=\"section-label\">How We Unite Communities</div>\n    <div class=\"pillars-grid\">\n      <div class=\"pillar-card\">\n        <svg class=\"pillar-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/>\n        </svg>\n        <div class=\"pillar-title\">Research-Driven</div>\n        <div class=\"pillar-desc\">Listening to neighbors facing hunger — their voices shape real solutions</div>\n      </div>\n      <div class=\"pillar-card\">\n        <svg class=\"pillar-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/>\n        </svg>\n        <div class=\"pillar-title\">Local to National</div>\n        <div class=\"pillar-desc\">Community wisdom turned into nationwide action every day</div>\n      </div>\n      <div class=\"pillar-card\">\n        <svg class=\"pillar-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M2 12h20\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/>\n        </svg>\n        <div class=\"pillar-title\">Nationwide Scale</div>\n        <div class=\"pillar-desc\">Moving food quickly and reliably to where it's needed most</div>\n      </div>\n      <div class=\"pillar-card\">\n        <svg class=\"pillar-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M18 8h1a4 4 0 0 1 0 8h-1\"/><path d=\"M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z\"/><path d=\"M6 1v3\"/><path d=\"M10 1v3\"/><path d=\"M14 1v3\"/>\n        </svg>\n        <div class=\"pillar-title\">Nutrition for All</div>\n        <div class=\"pillar-desc\">Making nutritious food accessible so everyone can lead healthier lives</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- CTA — Take Action -->\n  <section class=\"action-section animate delay-4\" aria-label=\"Take action\">\n    <div class=\"conversion-strip\">\n      <div class=\"conv-left\">\n        <div class=\"conv-number\">$1 = 10 meals</div>\n        <div class=\"conv-text\">Every dollar provides at<br>least 10 meals to neighbors</div>\n      </div>\n      <div class=\"conv-badge\">Gifts Matched</div>\n    </div>\n    <div class=\"cta-grid\">\n      <div class=\"cta-card\">\n        <svg class=\"cta-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/>\n        </svg>\n        <div class=\"cta-title\">Donate</div>\n        <div class=\"cta-desc\">Every $1 provides at least 10 meals. Gifts matched for a limited time.</div>\n      </div>\n      <div class=\"cta-card\">\n        <svg class=\"cta-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" y1=\"9\" x2=\"9.01\" y2=\"9\"/><line x1=\"15\" y1=\"9\" x2=\"15.01\" y2=\"9\"/>\n        </svg>\n        <div class=\"cta-title\">Advocate</div>\n        <div class=\"cta-desc\">Urge lawmakers to support programs that help neighbors facing hunger.</div>\n      </div>\n      <div class=\"cta-card\">\n        <svg class=\"cta-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/>\n        </svg>\n        <div class=\"cta-title\">Fundraise</div>\n        <div class=\"cta-desc\">Inspire your community to come together and make a collective difference.</div>\n      </div>\n      <div class=\"cta-card\">\n        <svg class=\"cta-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.