const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1080, height: 1520 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  // Wait for fonts + counter animations
  await page.waitForTimeout(3500);
  await page.screenshot({ path: '/app/output/final_poster.png', fullPage: false });
  await browser.close();
  console.log('PNG saved');
})();
